#!/usr/bin/env bash
# MYDA Studio — one-shot deploy script
# Generated automatically. Paste & run on the VPS as root.
#
# Behavior:
#   1. Installs nginx if missing (does not disturb any existing apache/nginx default vhosts)
#   2. Extracts the embedded site bundle to /var/www/myda
#   3. Writes an nginx server block for myda.contentclinic.co (HTTP only)
#   4. Tests + reloads nginx
#   5. Prints a curl-with-Host-header test you can run locally to verify
#      *before* DNS propagates.
#
# Run TLS step separately once DNS resolves:
#   certbot --nginx -d myda.contentclinic.co --non-interactive --agree-tos -m you@example.com

set -euo pipefail

DOMAIN="myda.contentclinic.co"
WEBROOT="/var/www/myda"
VHOST="/etc/nginx/sites-available/myda.contentclinic.co.conf"
VHOST_LINK="/etc/nginx/sites-enabled/myda.contentclinic.co.conf"

if [[ $EUID -ne 0 ]]; then
  echo "Run as root (sudo -i)." >&2
  exit 1
fi

echo "==> Installing nginx if needed..."
if ! command -v nginx >/dev/null 2>&1; then
  apt-get update -y
  DEBIAN_FRONTEND=noninteractive apt-get install -y nginx
fi

echo "==> Checking port 80 ownership..."
if ss -tlnp | grep -E ':80\b' | grep -vq nginx; then
  echo "WARNING: Something other than nginx is on port 80:"
  ss -tlnp | grep -E ':80\b' || true
  echo "Stopping conflicting services would break your existing site. Aborting."
  echo "If that other server is apache, you'll need to add a vhost there instead, or migrate."
  exit 2
fi

echo "==> Writing site to $WEBROOT..."
mkdir -p "$WEBROOT"
SITE_B64=""
echo "$SITE_B64" | base64 -d | tar -xzf - -C "$WEBROOT"
chown -R www-data:www-data "$WEBROOT" || true
echo "Site files:"
ls -la "$WEBROOT" | head -20

echo "==> Writing nginx vhost..."
cat > "$VHOST" <<NGINX
server {
    listen 80;
    listen [::]:80;
    server_name $DOMAIN;

    root $WEBROOT;
    index index.html;

    location / {
        try_files \$uri \$uri/ \$uri.html =404;
    }

    location ~* \.(?:css|js|png|jpe?g|gif|svg|webp|ico|woff2?)\$ {
        expires 7d;
        add_header Cache-Control "public, max-age=604800, immutable";
    }

    access_log /var/log/nginx/myda.access.log;
    error_log  /var/log/nginx/myda.error.log;
}
NGINX

ln -sfn "$VHOST" "$VHOST_LINK"

echo "==> Testing nginx config..."
nginx -t

echo "==> Reloading nginx..."
systemctl reload nginx || systemctl restart nginx

echo
echo "================================================================"
echo "DEPLOYED."
echo "Site root: $WEBROOT"
echo "Vhost:     $VHOST"
echo
echo "Test BEFORE DNS propagates (run from any machine):"
echo "  curl -sI -H 'Host: $DOMAIN' http://187.77.158.242/"
echo
echo "Once DNS resolves, get TLS:"
echo "  apt-get install -y certbot python3-certbot-nginx"
echo "  certbot --nginx -d $DOMAIN --non-interactive --agree-tos -m YOUR@EMAIL"
echo "================================================================"
